class Solution {
public:
    long long maxArrayValue(vector<int>& nums) {
        long long ans = 0;
        for (int i = (int)nums.size() - 1; i >= 0; i--)
            ans = (nums[i] <= ans) ? ans + nums[i] : nums[i];
        return ans;
    }
};

