class Solution {
    public long maxArrayValue(int[] nums) {
        Deque<Long> st = new ArrayDeque<>();
        for (int x : nums) {
            st.push((long) x);
            while (st.size() >= 2) {
                long a = st.pop(), b = st.peek();
                if (a <= b) st.push(a + b);
                else { st.push(a); break; }
            }
        }
        long ans = 0;
        for (long v : st) ans = Math.max(ans, v);
        return ans;
    }
}

