    const st = [];
    for (const x of nums) {
        st.push(x);
        while (st.length >= 2 && st[st.length - 2] <= st[st.length - 1])
            st.splice(st.length - 2, 2, st[st.length - 2] + st[st.length - 1]);
    }
    return Math.max(...st);
